#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const distRoot = path.join(root, "dist");
const outFile = path.join(distRoot, "_worker.js");

if (!fs.existsSync(distRoot)) {
  console.error('Run "npm run build" first to create dist/ before bundling the worker.');
  process.exit(1);
}

console.log("Bundling Merser3.1 worker ->", outFile);

await build({
  entryPoints: [path.join(root, "remote", "worker-source.mjs")],
  outfile: outFile,
  bundle: true,
  minify: true,
  format: "esm",
  platform: "browser",
  target: "es2022",
  conditions: ["workerd", "worker", "browser", "import", "module"],
  define: {
    "process.env.NODE_ENV": '"production"',
  },
  banner: {
    js: "// Merser3.1 by Skyes Over London - Cloudflare Pages Worker\n// Auto-generated by remote/build-remote-bundle.mjs\n",
  },
});

const routesPath = path.join(distRoot, "_routes.json");
if (!fs.existsSync(routesPath)) {
  fs.writeFileSync(routesPath, JSON.stringify({
    version: 1,
    include: ["/mcp", "/health", "/mcp/*"],
    exclude: ["/assets/*", "/*.js", "/*.css", "/*.html", "/*.png", "/*.jpg", "/*.svg", "/*.ico"],
  }, null, 2));
  console.log("Written _routes.json");
}

console.log("Done. Deploy with: npx wrangler pages deploy dist --project-name merser3-1");
